 71	// NewEnv creates new child scope.
 72	func (e *Env) NewEnv() *Env {
 73		return &Env{
 74			rwMutex: &sync.RWMutex{},
 75			parent:  e,
 76			values:  make(map[string]reflect.Value),
 77		}
