 86	func (s *Scanner) Init(src string) {
 87		s.src = []rune(src)
 88	}
 89	
 90	// Scan analyses token, and decide identify or literals.
 91	func (s *Scanner) Scan() (tok int, lit string, pos ast.Position, err error) {
 92	retry:
 93		s.skipBlank()
 94		pos = s.pos()
 95		switch ch := s.peek(); {
 96		case isLetter(ch):
 97			lit, err = s.scanIdentifier()
 98			if err != nil {
 99				return
100			}
101			if name, ok := opName[lit]; ok {
102				tok = name
103			} else {
104				tok = IDENT
105			}
106		case isDigit(ch):
107			tok = NUMBER
108			lit, err = s.scanNumber()
109			if err != nil {
110				return
111			}
112		case ch == '"':
113			tok = STRING
114			lit, err = s.scanString('"')
115			if err != nil {
116				return
117			}
118		case ch == '\'':
119			tok = STRING
120			lit, err = s.scanString('\'')
121			if err != nil {
122				return
123			}
124		case ch == '`':
125			tok = STRING
126			lit, err = s.scanRawString('`')
127			if err != nil {
128				return
129			}
130		default:
131			switch ch {
132			case EOF:
133				tok = EOF
134			case '#':
135				for !isEOL(s.peek()) {
136					s.next()
137				}
138				goto retry
139			case '!':
140				s.next()
141				switch s.peek() {
142				case '=':
143					tok = NEQ
144					lit = "!="
145				default:
146					s.back()
147					tok = int(ch)
148					lit = string(ch)
149				}
150			case '=':
151				s.next()
152				switch s.peek() {
153				case '=':
154					tok = EQEQ
155					lit = "=="
156				case ' ':
157					if s.peekPlus(1) == '<' && s.peekPlus(2) == '-' {
158						s.next()
159						s.next()
160						tok = EQOPCHAN
161						lit = "= <-"
162					} else {
163						s.back()
164						tok = int(ch)
165						lit = string(ch)
166					}
167				default:
168					s.back()
169					tok = int(ch)
170					lit = string(ch)
171				}
172			case '?':
173				s.next()
174				switch s.peek() {
175				case '?':
176					tok = NILCOALESCE
177					lit = "??"
178				default:
179					s.back()
180					tok = int(ch)
181					lit = string(ch)
182				}
183			case '+':
184				s.next()
185				switch s.peek() {
186				case '+':
187					tok = PLUSPLUS
188					lit = "++"
189				case '=':
190					tok = PLUSEQ
191					lit = "+="
192				default:
193					s.back()
194					tok = int(ch)
195					lit = string(ch)
196				}
197			case '-':
198				s.next()
199				switch s.peek() {
200				case '-':
201					tok = MINUSMINUS
202					lit = "--"
203				case '=':
204					tok = MINUSEQ
205					lit = "-="
206				default:
207					s.back()
208					tok = int(ch)
209					lit = "-"
210				}
211			case '*':
212				s.next()
213				switch s.peek() {
214				case '=':
215					tok = MULEQ
216					lit = "*="
217				default:
218					s.back()
219					tok = int(ch)
220					lit = string(ch)
221				}
222			case '/':
223				s.next()
224				switch s.peek() {
225				case '=':
226					tok = DIVEQ
227					lit = "/="
228				case '/':
229					for !isEOL(s.peek()) {
230						s.next()
231					}
232					goto retry
233				case '*':
234					for {
235						_, err = s.scanRawString('*')
236						if err != nil {
237							return
238						}
239	
240						if s.peek() == '/' {
241							s.next()
242							goto retry
243						}
244	
245						s.back()
246					}
247				default:
248					s.back()
249					tok = int(ch)
250					lit = string(ch)
251				}
252			case '>':
253				s.next()
254				switch s.peek() {
255				case '=':
256					tok = GE
257					lit = ">="
258				case '>':
259					tok = SHIFTRIGHT
260					lit = ">>"
261				default:
262					s.back()
263					tok = int(ch)
264					lit = string(ch)
265				}
266			case '<':
267				s.next()
268				switch s.peek() {
269				case '-':
270					tok = OPCHAN
271					lit = "<-"
272				case '=':
273					tok = LE
274					lit = "<="
275				case '<':
276					tok = SHIFTLEFT
277					lit = "<<"
278				default:
279					s.back()
280					tok = int(ch)
281					lit = string(ch)
282				}
283			case '|':
284				s.next()
285				switch s.peek() {
286				case '|':
287					tok = OROR
288					lit = "||"
289				case '=':
290					tok = OREQ
291					lit = "|="
292				default:
293					s.back()
294					tok = int(ch)
295					lit = string(ch)
296				}
297			case '&':
298				s.next()
299				switch s.peek() {
300				case '&':
301					tok = ANDAND
302					lit = "&&"
303				case '=':
304					tok = ANDEQ
305					lit = "&="
306				default:
307					s.back()
308					tok = int(ch)
309					lit = string(ch)
310				}
311			case '.':
312				s.next()
313				if s.peek() == '.' {
314					s.next()
315					if s.peek() == '.' {
316						tok = VARARG
317					} else {
318						err = fmt.Errorf("syntax error on '%v' at %v:%v", string(ch), pos.Line, pos.Column)
319						return
320					}
321				} else {
322					s.back()
323					tok = int(ch)
324					lit = string(ch)
325				}
326			case '\n', '(', ')', ':', ';', '%', '{', '}', '[', ']', ',', '^':
327				tok = int(ch)
328				lit = string(ch)
329			default:
330				err = fmt.Errorf("syntax error on '%v' at %v:%v", string(ch), pos.Line, pos.Column)
331				tok = int(ch)
332				lit = string(ch)
333				return
334			}
335			s.next()
336		}
337		return
338	}
