// DefineValue defines/sets reflect value to symbol in current scope.
// The new binding does not keep any type constraint previously declared for symbol.
func (e *Env) DefineValue(symbol string, value reflect.Value) error {
	if strings.Contains(symbol, ".") {
		return ErrSymbolContainsDot
	}
	e.rwMutex.Lock()
	e.values[symbol] = value
	if e.valueConstraints != nil {
		delete(e.valueConstraints, symbol)
	}
	e.rwMutex.Unlock()

	return nil
}

// DefineTypedValue defines/sets reflect value to symbol in current scope and
// records constraintType as the type constraint of the new binding.
func (e *Env) DefineTypedValue(symbol string, value reflect.Value, constraintType reflect.Type) error {
	if strings.Contains(symbol, ".") {
		return ErrSymbolContainsDot
	}
	e.rwMutex.Lock()
	e.values[symbol] = value
	if e.valueConstraints == nil {
		e.valueConstraints = make(map[string]reflect.Type)
	}
	e.valueConstraints[symbol] = constraintType
	e.rwMutex.Unlock()

	return nil
}

// TypeConstraint returns the type constraint of symbol from the scope where
// symbol is first found, like SetValue would. The second return value is false
// when symbol is not found or its binding has no type constraint.
func (e *Env) TypeConstraint(symbol string) (reflect.Type, bool) {
	e.rwMutex.RLock()
	_, found := e.values[symbol]
	if found {
		constraintType, ok := e.valueConstraints[symbol]
		e.rwMutex.RUnlock()
		return constraintType, ok
	}
	e.rwMutex.RUnlock()

	if e.parent == nil {
		return nil, false
	}
	return e.parent.TypeConstraint(symbol)
}

