package vm

import (
	"fmt"
	"reflect"
)

// checkTypedBinding checks that value may be assigned to a variable declared
// with the given constraint type. It returns the value to bind, which for a
// nil assignment is the zero value of the constraint type. No implicit type
// conversion is performed: the value type must be identical to the constraint
// type, or satisfy it when the constraint type is an interface.
func checkTypedBinding(name string, value reflect.Value, constraintType reflect.Type) (reflect.Value, error) {
	if value.Kind() == reflect.Interface && !value.IsNil() {
		value = value.Elem()
	}

	if !value.IsValid() || (value.Kind() == reflect.Interface && value.IsNil()) {
		// nil assignment
		switch constraintType.Kind() {
		case reflect.Interface, reflect.Slice, reflect.Map, reflect.Ptr, reflect.Chan:
			return reflect.Zero(constraintType), nil
		}
		return nilValue, fmt.Errorf("type error: cannot assign type <nil> to variable '%s' of type %s", name, constraintType.String())
	}

	if value.Type() == constraintType {
		return value, nil
	}

	if constraintType.Kind() == reflect.Interface && value.Type().Implements(constraintType) {
		return value, nil
	}

	return nilValue, fmt.Errorf("type error: cannot assign type %s to variable '%s' of type %s", value.Type().String(), name, constraintType.String())
}

// defineVar binds name to value in the current scope for a var statement.
// For a typed declaration with TypedBindings enabled, the value is checked
// against the declared type and the new binding keeps the type constraint.
// In every other case the new binding is dynamic and keeps no constraint.
func (runInfo *runInfoStruct) defineVar(name string, value reflect.Value, constraintType reflect.Type) error {
	if constraintType != nil && runInfo.options.TypedBindings && name != "_" {
		checkedValue, err := checkTypedBinding(name, value, constraintType)
		if err != nil {
			return err
		}
		return runInfo.env.DefineTypedValue(name, checkedValue, constraintType)
	}
	return runInfo.env.DefineValue(name, value)
}

