package env

import (
	"reflect"
	"testing"
)

func TestDefineTypedValue(t *testing.T) {
	e := NewEnv()
	int64Type := reflect.TypeOf(int64(1))

	err := e.DefineTypedValue("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}

	value, err := e.Get("a")
	if err != nil {
		t.Fatal("Get error:", err)
	}
	if value != int64(1) {
		t.Fatalf("value - received: %v - expected: %v", value, int64(1))
	}

	constraintType, ok := e.TypeConstraint("a")
	if !ok {
		t.Fatal("TypeConstraint - received: false - expected: true")
	}
	if constraintType != int64Type {
		t.Fatalf("constraint type - received: %v - expected: %v", constraintType, int64Type)
	}

	err = e.DefineTypedValue("a.a", reflect.ValueOf(int64(1)), int64Type)
	if err != ErrSymbolContainsDot {
		t.Fatalf("DefineTypedValue error - received: %v - expected: %v", err, ErrSymbolContainsDot)
	}
}

func TestTypeConstraintScopes(t *testing.T) {
	int64Type := reflect.TypeOf(int64(1))
	stringType := reflect.TypeOf("a")

	// constraint of undefined symbol
	e := NewEnv()
	_, ok := e.TypeConstraint("a")
	if ok {
		t.Fatal("TypeConstraint - received: true - expected: false")
	}

	// constraint is found from the scope where the symbol is found
	err := e.DefineTypedValue("a", reflect.ValueOf(int64(1)), int64Type)
	if err != nil {
		t.Fatal("DefineTypedValue error:", err)
	}
	child := e.NewEnv()
	constraintType, ok := child.TypeConstraint("a")
	if !ok || constraintType != int64Type {
		t.Fatalf("TypeConstraint - received: %v, %v - expected: %v, true", constraintType, ok, int64Type)
	}

	// shadowing binding without constraint hides the parent constraint
	err = child.DefineValue("a", reflect.ValueOf("a"))
	if err != nil {
		t.Fatal("DefineValue error:", err)
	}
	_, ok = child.TypeConstraint("a")
	if ok {
		t.Fatal("TypeConstraint - received: true - expected: false")
	}

	// shadowing binding with another constraint
	err = child.DefineTypedValue("a", reflect.ValueOf("a"), stringType)
	if err != nil {
