import (
	"fmt"
	"strings"
	"github.com/mattn/anko/env"
	"github.com/mattn/anko/vm"
)

// verify required error-message contents
func main() {
	on := &vm.Options{TypedBindings: true}
	checks := []struct {
		src      string
		contains []string
	}{
		{`var x: int64 = "a"`, []string{"type error", "x", "string", "int64"}},
		{`var x: int64 = nil`, []string{"type error", "x", "<nil>", "int64"}},
